use std::collections::BTreeMap;
use std::error::Error;
use std::fmt;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use model::Inventory;

pub const SCHEMA: &str = "soma-record-index-v1";
pub const MARKDOWN_MARKER: &str =
    "<!-- GENERATED BY soma-record-index; NON-AUTHORITATIVE; DO NOT EDIT. -->";
pub const TEXT_MARKER: &str = "# GENERATED BY soma-record-index; NON-AUTHORITATIVE; DO NOT EDIT.";

#[derive(Debug)]
pub enum IndexError {
    Io {
        operation: &'static str,
        path: PathBuf,
        source: io::Error,
    },
    RootNotFound {
        start: PathBuf,
    },
    MissingSource {
        path: PathBuf,
    },
    InvalidSource {
        path: PathBuf,
        line: Option<usize>,
        message: String,
    },
    NonUtf8Path {
        path: PathBuf,
    },
    DuplicateId {
        id: String,
        first: String,
        second: String,
    },
    MissingAllocation {
        kind: String,
        alias: String,
    },
    UnusedAllocation {
        id: String,
        alias: String,
    },
    UnsafeOutput {
        path: PathBuf,
        reason: String,
    },
    ForeignOutput {
        path: PathBuf,
    },
    Drift {
        path: PathBuf,
        reason: String,
    },
    Usage(String),
}

impl IndexError {
    pub fn io(operation: &'static str, path: PathBuf, source: io::Error) -> Self {
        Self::Io {
            operation,
            path,
            source,
        }
    }

    pub fn usage(message: impl Into<String>) -> Self {
        Self::Usage(message.into())
    }

    pub(crate) fn invalid(
        path: impl Into<PathBuf>,
        line: Option<usize>,
        message: impl Into<String>,
    ) -> Self {
        Self::InvalidSource {
            path: path.into(),
            line,
            message: message.into(),
        }
    }
}

impl fmt::Display for IndexError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Io {
                operation,
                path,
                source,
            } => write!(formatter, "cannot {operation} {}: {source}", path.display()),
            Self::RootNotFound { start } => write!(
                formatter,
                "could not find a laboratory root above {} (expected src/soma/FORMULA.md and .agents/COMMUNE)",
                start.display()
            ),
            Self::MissingSource { path } => {
                write!(formatter, "required source is missing: {}", path.display())
            }
            Self::InvalidSource {
                path,
                line,
                message,
            } => {
                write!(formatter, "invalid source {}", path.display())?;
                if let Some(line) = line {
                    write!(formatter, ":{line}")?;
                }
                write!(formatter, ": {message}")
            }
            Self::NonUtf8Path { path } => write!(
                formatter,
                "source path is not valid UTF-8 and cannot receive a deterministic alias: {}",
                path.display()
            ),
            Self::DuplicateId { id, first, second } => write!(
                formatter,
                "canonical ID {id} is assigned twice: {first} and {second}"
            ),
            Self::MissingAllocation { kind, alias } => write!(
                formatter,
                "{kind} discovery alias {alias:?} has no durable allocation; append an allocation before generating"
            ),
            Self::UnusedAllocation { id, alias } => write!(
                formatter,
                "allocation {id} ({alias}) no longer resolves; update its alias explicitly if the source moved"
            ),
            Self::UnsafeOutput { path, reason } => {
                write!(formatter, "refusing output directory {}: {reason}", path.display())
            }
            Self::ForeignOutput { path } => write!(
                formatter,
                "refusing to overwrite non-generated file {}",
                path.display()
            ),
            Self::Drift { path, reason } => {
                write!(formatter, "generated index drift at {}: {reason}", path.display())
            }
            Self::Usage(message) => formatter.write_str(message),
        }
    }
}

impl Error for IndexError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            Self::Io { source, .. } => Some(source),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct Counts {
    pub formula_claims: usize,
    pub research_documents: usize,
    pub observation_records: usize,
    pub observations: usize,
    pub correspondence: usize,
    pub ledger_entries: usize,
    pub crates: usize,
    pub public_symbols: usize,
    pub abi_identifiers: usize,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub struct GeneratedIndex {
    files: BTreeMap<String, String>,
    counts: Counts,
}

impl GeneratedIndex {
    pub fn files(&self) -> &BTreeMap<String, String> {
        &self.files
    }

    pub fn counts(&self) -> &Counts {
        &self.counts
    }
}

pub fn discover_laboratory_root(start: &Path) -> Result<PathBuf, IndexError> {
    for candidate in start.ancestors() {
        if candidate.join("src/soma/FORMULA.md").is_file()
            && candidate.join(".agents/COMMUNE").is_dir()
        {
            return Ok(candidate.to_path_buf());
        }
    }
    Err(IndexError::RootNotFound {
        start: start.to_path_buf(),
    })
}

pub fn generate(root: &Path) -> Result<GeneratedIndex, IndexError> {
    let root = canonical_directory(root)?;
    let inventory = scan::inventory(&root)?;
    let counts = counts(&inventory);
    let files = render::render(&inventory, &counts);
    Ok(GeneratedIndex { files, counts })
}

pub fn write_generated(
    root: &Path,
    output: &Path,
    generated: &GeneratedIndex,
) -> Result<(), IndexError> {
    let root = canonical_directory(root)?;
    let output = absolute_path(output)?;
    validate_output_boundary(&root, &output)?;
    fs::create_dir_all(&output)
        .map_err(|source| IndexError::io("create output directory", output.clone(), source))?;
    let output = canonical_directory(&output)?;
    validate_output_boundary(&root, &output)?;

    for (name, contents) in generated.files() {
        let path = output.join(name);
        if path.exists() {
            let existing = fs::read_to_string(&path)
                .map_err(|source| IndexError::io("read existing output", path.clone(), source))?;
            if !owns_output(&existing) {
                return Err(IndexError::ForeignOutput { path });
            }
        }
        debug_assert!(owns_output(contents));
    }
    for (name, contents) in generated.files() {
        let path = output.join(name);
        fs::write(&path, contents)
            .map_err(|source| IndexError::io("write generated index", path, source))?;
    }
    Ok(())
}

pub fn check_generated(
    root: &Path,
    output: &Path,
    generated: &GeneratedIndex,
) -> Result<(), IndexError> {
    let root = canonical_directory(root)?;
    let output = absolute_path(output)?;
    validate_output_boundary(&root, &output)?;
    if !output.is_dir() {
        return Err(IndexError::Drift {
            path: output,
            reason: "output directory is missing".to_string(),
        });
    }
    let output = canonical_directory(&output)?;
    validate_output_boundary(&root, &output)?;
    for (name, expected) in generated.files() {
        let path = output.join(name);
        let actual = fs::read_to_string(&path).map_err(|source| {
            if source.kind() == io::ErrorKind::NotFound {
                IndexError::Drift {
                    path: path.clone(),
                    reason: "generated file is missing".to_string(),
                }
            } else {
                IndexError::io("read generated index", path.clone(), source)
            }
        })?;
        if actual != *expected {
            return Err(IndexError::Drift {
                path,
                reason: "contents differ from the deterministic render".to_string(),
            });
        }
    }
    Ok(())
}

fn counts(inventory: &Inventory) -> Counts {
    Counts {
        formula_claims: inventory.formula.len(),
        research_documents: inventory.research.len(),
        observation_records: inventory.observations.len(),
        observations: inventory
            .observations
            .iter()
            .map(|entry| &entry.observation_id)
            .collect::<std::collections::BTreeSet<_>>()
            .len(),
        correspondence: inventory.correspondence.len(),
        ledger_entries: inventory.ledger.len(),
        crates: inventory.crates.len(),
        public_symbols: inventory.public_symbols.len(),
        abi_identifiers: inventory.abi.len(),
    }
}

fn owns_output(contents: &str) -> bool {
    contents.starts_with(MARKDOWN_MARKER) || contents.starts_with(TEXT_MARKER)
}

fn canonical_directory(path: &Path) -> Result<PathBuf, IndexError> {
    if !path.is_dir() {
        return Err(IndexError::MissingSource {
            path: path.to_path_buf(),
        });
    }
    fs::canonicalize(path)
        .map_err(|source| IndexError::io("canonicalize directory", path.to_path_buf(), source))
}

fn absolute_path(path: &Path) -> Result<PathBuf, IndexError> {
    if path.is_absolute() {
        Ok(path.to_path_buf())
    } else {
        let current = std::env::current_dir().map_err(|source| {
            IndexError::io("read current directory", PathBuf::from("."), source)
        })?;
        Ok(current.join(path))
    }
}

fn validate_output_boundary(root: &Path, output: &Path) -> Result<(), IndexError> {
    let protected = [
        root.to_path_buf(),
        root.join("src/soma"),
        root.join("src/soma/RESEARCH"),
        root.join("src/soma/observations"),
        root.join(".agents"),
        root.join(".agents/COMMUNE"),
    ];
    for boundary in protected {
        if output == boundary
            || output.starts_with(root.join("src/soma/RESEARCH"))
            || output.starts_with(root.join("src/soma/observations"))
            || output.starts_with(root.join(".agents/COMMUNE"))
            || boundary.starts_with(output)
        {
            return Err(IndexError::UnsafeOutput {
                path: output.to_path_buf(),
                reason: "it overlaps an authoritative source boundary".to_string(),
            });
        }
    }
    Ok(())
}

